2315	new file mode 100644
2316	index 0000000..7f10579
2317	--- /dev/null
2318	+++ b/seed-a-backend.Tests/SqlServerTestDatabase.cs
2319	@@ -0,0 +1,49 @@
2320	+using Microsoft.Data.SqlClient;
2321	+using Microsoft.EntityFrameworkCore;
2322	+using seed_a_backend.Api.Infrastructure;
2323	+
2324	+namespace seed_a_backend.Tests;
2325	+
2326	+/// <summary>
2327	+/// Erstellt für jede Testklasse eine eigene, eindeutig benannte Testdatenbank auf dem echten
2328	+/// SQL Server aus ConnectionStrings__Default (Consistency Convention „Test-Engine für
2329	+/// Nebenläufigkeit“ — kein EF-Core-InMemory-Provider, da gefilterte Unique-Constraints sonst
2330	+/// nicht durchgesetzt würden). Schema wird über die echten EF-Core-Migrations aufgebaut, damit
2331	+/// die Migration selbst mitgetestet wird.
2332	+/// </summary>
2333	+public sealed class SqlServerTestDatabase : IAsyncLifetime
2334	+{
2335	+    private readonly string _connectionString;
2336	+
2337	+    public SqlServerTestDatabase()
2338	+    {
2339	+        var baseConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
2340	+            ?? throw new InvalidOperationException("ConnectionStrings__Default ist für die Tests nicht gesetzt.");
2341	+
2342	+        var builder = new SqlConnectionStringBuilder(baseConnectionString)
2343	+        {
2344	+            InitialCatalog = $"seed_a_test_{Guid.NewGuid():N}",
2345	+        };
2346	+        _connectionString = builder.ConnectionString;
2347	+    }
2348	+
2349	+    public AppDbContext CreateContext()
2350	+    {
2351	+        var options = new DbContextOptionsBuilder<AppDbContext>()
2352	+            .UseSqlServer(_connectionString)
2353	+            .Options;
2354	+        return new AppDbContext(options);
2355	+    }
2356	+
2357	+    public async ValueTask InitializeAsync()
2358	+    {
2359	+        await using var db = CreateContext();
2360	+        await db.Database.MigrateAsync();
2361	+    }
2362	+
2363	+    public async ValueTask DisposeAsync()
2364	+    {
2365	+        await using var db = CreateContext();
2366	+        await db.Database.EnsureDeletedAsync();
2367	+    }
2368	+}
