1272	+    /// Ausnahmen (z. B. ArgumentNullException bei Dictionary-Keys) statt einer beschreibenden
1273	+    /// Fehlermeldung führen.
1274	+    /// </summary>
1275	+    private static string RequireNonNull(string? value, string errorMessage) =>
1276	+        value ?? throw new InvalidOperationException(errorMessage);
1277	+
1278	+    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
1279	+    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
1280	+    {
1281	+        var digitsStart = 0;
1282	+        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
1283	+        {
1284	+            digitsStart++;
1285	+        }
1286	+
1287	+        var digitsEnd = digitsStart;
1288	+        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
1289	+        {
1290	+            digitsEnd++;
1291	+        }
1292	+
1293	+        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length
1294	+            || !int.TryParse(sitzplatz[digitsStart..], out var columnNumber))
1295	+        {
1296	+            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
1297	+        }
1298	+
1299	+        var rowLabel = sitzplatz[..digitsStart];
1300	+        return (rowLabel, columnNumber);
1301	+    }
1302	+}
